use anyhow::{anyhow, Context, Result};
use std::fs;

pub fn load_port(path: &str) -> Result<u16> {
    let text = fs::read_to_string(path).context("cannot read config")?;
    let line = text
        .lines()
        .find(|line| line.starts_with("port="))
        .ok_or_else(|| anyhow!("no port= line"))?;
    Ok(line.trim_start_matches("port=").parse()?)
}

use anyhow::{Context, Result};

pub fn load_port(path: &str) -> Result<u16> {
    let text = fs::read_to_string(path).context("cannot read config")?;
    let Some(line) = text.lines().find(|line| line.starts_with("port=")) else {
        return Ok(8080);
    };
    Ok(line.trim_start_matches("port=").parse()?)
}
